<?php
declare(strict_types=1);
$root=dirname(__DIR__);require_once $root.'/config/config.php';require_once $root.'/includes/services/MercenaryMarketService.php';
$pdo=db();$playerId=(int)$pdo->query("SELECT id FROM players WHERE username='demo' LIMIT 1")->fetchColumn();$type=$pdo->query('SELECT id,name,price,capacity_cost FROM mercenary_types ORDER BY id LIMIT 1')->fetch(PDO::FETCH_ASSOC);if($playerId<1||!$type){fwrite(STDERR,"mercenary_seed_missing\n");exit(2);}$id=(int)$type['id'];$res=$pdo->prepare('SELECT naquadah,population,population_capacity FROM player_resources WHERE player_id=?');$res->execute([$playerId]);$before=$res->fetch(PDO::FETCH_ASSOC);$owned=$pdo->prepare('SELECT quantity FROM player_mercenaries WHERE player_id=? AND mercenary_type_id=?');$owned->execute([$playerId,$id]);$ownedBefore=(int)($owned->fetchColumn()?:0);$pdo->prepare("DELETE FROM player_cooldowns WHERE player_id=? AND cooldown_key='mercenary_buy'")->execute([$playerId]);$service=new MercenaryMarketService($pdo);$result=$service->buy($playerId,$id,1,2);$scarcity=1+((int)$type['capacity_cost']*0.1);$expected=(int)ceil((int)$type['price']*2*$scarcity);$checks=['cost_formula'=>(int)$result['cost']===$expected,'quantity'=>(int)$result['quantity']===1,'duration'=>(int)$result['duration_days']===2,'capacity_metadata'=>(int)$result['capacity_cost']===(int)$type['capacity_cost'],'roster_updated'=>true];$owned->execute([$playerId,$id]);$checks['roster_updated']=(int)$owned->fetchColumn()===$ownedBefore+1;$res->execute([$playerId]);$after=$res->fetch(PDO::FETCH_ASSOC);$checks['resource_deducted']=(int)$after['naquadah']===(int)$before['naquadah']-$expected;$event=$pdo->prepare("SELECT payload FROM game_events WHERE player_id=? AND event_type='mercenary_recruited' AND entity_id=? ORDER BY id DESC LIMIT 1");$event->execute([$playerId,$id]);$payload=json_decode((string)$event->fetchColumn(),true);$checks['audit_metadata']=is_array($payload)&&isset($payload['duration_days'],$payload['scarcity_modifier'],$payload['capacity_cost'],$payload['contract_expires_at']);$owned->execute([$playerId,$id]);$ownedAfter=(int)$owned->fetchColumn();$pdo->prepare('UPDATE player_mercenaries SET quantity=? WHERE player_id=? AND mercenary_type_id=?')->execute([$ownedBefore,$playerId,$id]);$pdo->prepare('UPDATE player_resources SET naquadah=? WHERE player_id=?')->execute([(int)$before['naquadah'],$playerId]);$pdo->prepare("DELETE FROM game_events WHERE player_id=? AND event_type='mercenary_recruited' AND entity_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL 2 MINUTE)")->execute([$playerId,$id]);$pdo->prepare("DELETE FROM player_cooldowns WHERE player_id=? AND cooldown_key='mercenary_buy'")->execute([$playerId]);$failures=array_keys(array_filter($checks,static fn(bool $ok):bool=>!$ok));echo json_encode(['status'=>$failures?'failed':'passed','result'=>$result,'checks'=>$checks,'failures'=>$failures],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR).PHP_EOL;exit($failures?1:0);
